    "model_solution": {
      "html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>20 - Custom Range Slider</title>\n    <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700;800&family=Fira+Code:wght@500&display=swap\" rel=\"stylesheet\">\n    <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n    <div class=\"container\">\n        <header class=\"header\">\n            <span class=\"badge\">Question 20 \u2022 Level 2: Components</span>\n            <h1>Custom Range Slider & Floating Value</h1>\n            <p>Calculates thumb position offsets in real-time with dual-color dynamic progress tracks.</p>\n        </header>\n\n        <div class=\"slider-card\">\n            <h2>Budget Allocation Range</h2>\n            \n            <div class=\"range-wrapper\">\n                <div class=\"floating-tooltip\" id=\"sliderTooltip\">$2,500</div>\n                <input type=\"range\" id=\"budgetRange\" min=\"500\" max=\"10000\" step=\"100\" value=\"2500\">\n            </div>\n\n            <div class=\"range-limits\">\n                <span>Min: $500</span>\n                <span>Max: $10,000</span>\n            </div>\n\n            <div class=\"calculated-output\">\n                <div class=\"calc-row\">\n                    <span>Selected Monthly Budget:</span>\n                    <strong id=\"finalValue\">$2,500</strong>\n                </div>\n            </div>\n        </div>\n    </div>\n    <script src=\"script.js\"></script>\n</body>\n</html>",
      "css": "* {\n    margin: 0;\n    padding: 0;\n    box-sizing: border-box;\n}\n\nbody {\n    background: #0b0f19;\n    color: #f8fafc;\n    font-family: 'Plus Jakarta Sans', sans-serif;\n    min-height: 100vh;\n    padding: 3rem 1rem;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n}\n\n.container {\n    max-width: 550px;\n    width: 100%;\n}\n\n.header {\n    text-align: center;\n    margin-bottom: 2rem;\n}\n\n.badge {\n    display: inline-block;\n    background: rgba(99, 102, 241, 0.15);\n    color: #818cf8;\n    padding: 4px 12px;\n    border-radius: 999px;\n    font-size: 0.85rem;\n    font-weight: 700;\n    margin-bottom: 0.5rem;\n}\n\n.header h1 {\n    font-size: 2.2rem;\n    margin-bottom: 0.4rem;\n}\n\n.header p {\n    color: #94a3b8;\n}\n\n.slider-card {\n    background: #131b2e;\n    border: 1px solid #1e293b;\n    border-radius: 18px;\n    padding: 2.5rem 2rem 2rem;\n    box-shadow: 0 15px 35px rgba(0,0,0,0.4);\n}\n\n.slider-card h2 {\n    font-size: 1.3rem;\n    margin-bottom: 2.5rem;\n    text-align: center;\n}\n\n.range-wrapper {\n    position: relative;\n    margin-bottom: 1.5rem;\n}\n\n.floating-tooltip {\n    position: absolute;\n    top: -45px;\n    left: 50%;\n    transform: translateX(-50%);\n    background: #4f46e5;\n    color: white;\n    font-family: 'Fira Code', monospace;\n    font-size: 0.85rem;\n    font-weight: 700;\n    padding: 4px 10px;\n    border-radius: 6px;\n    pointer-events: none;\n    box-shadow: 0 4px 10px rgba(79, 70, 229, 0.4);\n}\n\n.floating-tooltip::after {\n    content: '';\n    position: absolute;\n    bottom: -5px;\n    left: 50%;\n    transform: translateX(-50%);\n    border-width: 5px 5px 0;\n    border-style: solid;\n    border-color: #4f46e5 transparent transparent;\n}\n\ninput[type=\"range\"] {\n    -webkit-appearance: none;\n    width: 100%;\n    height: 8px;\n    border-radius: 99px;\n    background: #1e293b;\n    outline: none;\n    cursor: pointer;\n}\n\ninput[type=\"range\"]::-webkit-slider-thumb {\n    -webkit-appearance: none;\n    width: 24px;\n    height: 24px;\n    border-radius: 50%;\n    background: #ffffff;\n    border: 3px solid #4f46e5;\n    box-shadow: 0 0 10px rgba(0,0,0,0.3);\n    cursor: pointer;\n    transition: transform 0.1s;\n}\n\ninput[type=\"range\"]::-webkit-slider-thumb:hover {\n    transform: scale(1.2);\n}\n\n.range-limits {\n    display: flex;\n    justify-content: space-between;\n    font-size: 0.85rem;\n    color: #64748b;\n    margin-bottom: 2rem;\n}\n\n.calculated-output {\n    background: #0b0f19;\n    border: 1px solid #1e293b;\n    border-radius: 10px;\n    padding: 1.2rem;\n}\n\n.calc-row {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n}\n\n.calc-row span { color: #94a3b8; }\n.calc-row strong { font-size: 1.3rem; color: #38bdf8; font-family: 'Fira Code', monospace; }",
      "js": "const range = document.getElementById('budgetRange');\nconst tooltip = document.getElementById('sliderTooltip');\nconst finalValue = document.getElementById('finalValue');\n\nfunction updateSlider() {\n    const val = parseInt(range.value);\n    const min = parseInt(range.min);\n    const max = parseInt(range.max);\n\n    const percent = (val - min) / (max - min);\n    \n    // Dynamic progress color fill\n    range.style.background = `linear-gradient(to right, #4f46e5 0%, #4f46e5 ${percent * 100}%, #1e293b ${percent * 100}%, #1e293b 100%)`;\n\n    // Tooltip position\n    const thumbWidth = 24;\n    const offset = percent * (range.offsetWidth - thumbWidth) + (thumbWidth / 2);\n    tooltip.style.left = `${offset}px`;\n\n    const formatted = `$${val.toLocaleString()}`;\n    tooltip.textContent = formatted;\n    finalValue.textContent = formatted;\n}\n\nrange.addEventListener('input', updateSlider);\nwindow.addEventListener('resize', updateSlider);\n\nupdateSlider();"
    }
