      "html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>22 - Tooltip & Popover System</title>\n    <link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700;800&display=swap\" rel=\"stylesheet\">\n    <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n    <div class=\"container\">\n        <header class=\"header\">\n            <span class=\"badge\">Question 22 \u2022 Level 2: Components</span>\n            <h1>Tooltip & Popover Engine</h1>\n            <p>CSS data-attributes and pseudo-elements providing 4 cardinal positioning directions.</p>\n        </header>\n\n        <div class=\"card\">\n            <h2>Hover Over Any Directional Button</h2>\n            \n            <div class=\"tooltips-grid\">\n                <button class=\"btn has-tooltip\" data-tooltip=\"Tooltip displayed on Top\" data-position=\"top\">\u2b06\ufe0f Top Tooltip</button>\n                <button class=\"btn has-tooltip\" data-tooltip=\"Tooltip displayed on Bottom\" data-position=\"bottom\">\u2b07\ufe0f Bottom Tooltip</button>\n                <button class=\"btn has-tooltip\" data-tooltip=\"Tooltip displayed on Left\" data-position=\"left\">\u2b05\ufe0f Left Tooltip</button>\n                <button class=\"btn has-tooltip\" data-tooltip=\"Tooltip displayed on Right\" data-position=\"right\">\u27a1\ufe0f Right Tooltip</button>\n            </div>\n        </div>\n    </div>\n    <script src=\"script.js\"></script>\n</body>\n</html>",
      "css": "* {\n    margin: 0;\n    padding: 0;\n    box-sizing: border-box;\n}\n\nbody {\n    background: #0b0f19;\n    color: #f8fafc;\n    font-family: 'Plus Jakarta Sans', sans-serif;\n    min-height: 100vh;\n    padding: 3rem 1rem;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n}\n\n.container {\n    max-width: 650px;\n    width: 100%;\n}\n\n.header {\n    text-align: center;\n    margin-bottom: 2rem;\n}\n\n.badge {\n    display: inline-block;\n    background: rgba(99, 102, 241, 0.15);\n    color: #818cf8;\n    padding: 4px 12px;\n    border-radius: 999px;\n    font-size: 0.85rem;\n    font-weight: 700;\n    margin-bottom: 0.5rem;\n}\n\n.header h1 {\n    font-size: 2.2rem;\n    margin-bottom: 0.4rem;\n}\n\n.header p {\n    color: #94a3b8;\n}\n\n.card {\n    background: #131b2e;\n    border: 1px solid #1e293b;\n    border-radius: 18px;\n    padding: 3rem 2rem;\n    text-align: center;\n    box-shadow: 0 15px 35px rgba(0,0,0,0.4);\n}\n\n.card h2 {\n    font-size: 1.3rem;\n    margin-bottom: 2.5rem;\n}\n\n.tooltips-grid {\n    display: flex;\n    justify-content: center;\n    gap: 20px;\n    flex-wrap: wrap;\n}\n\n.btn {\n    background: #1e293b;\n    border: 1px solid #334155;\n    color: #f8fafc;\n    padding: 0.8rem 1.4rem;\n    border-radius: 10px;\n    font-weight: 700;\n    cursor: pointer;\n    position: relative;\n    transition: all 0.2s;\n}\n\n.btn:hover {\n    border-color: #38bdf8;\n    color: #38bdf8;\n}\n\n/* Tooltip Data Engine */\n.has-tooltip::before {\n    content: attr(data-tooltip);\n    position: absolute;\n    background: #1e1b4b;\n    color: #c7d2fe;\n    border: 1px solid #4338ca;\n    padding: 6px 12px;\n    border-radius: 6px;\n    font-size: 0.8rem;\n    white-space: nowrap;\n    pointer-events: none;\n    opacity: 0;\n    visibility: hidden;\n    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n    z-index: 50;\n}\n\n/* Top */\n.has-tooltip[data-position=\"top\"]::before {\n    bottom: 100%;\n    left: 50%;\n    transform: translateX(-50%) translateY(-6px);\n}\n.has-tooltip[data-position=\"top\"]:hover::before {\n    opacity: 1;\n    visibility: visible;\n    transform: translateX(-50%) translateY(-12px);\n}\n\n/* Bottom */\n.has-tooltip[data-position=\"bottom\"]::before {\n    top: 100%;\n    left: 50%;\n    transform: translateX(-50%) translateY(6px);\n}\n.has-tooltip[data-position=\"bottom\"]:hover::before {\n    opacity: 1;\n    visibility: visible;\n    transform: translateX(-50%) translateY(12px);\n}\n\n/* Left */\n.has-tooltip[data-position=\"left\"]::before {\n    right: 100%;\n    top: 50%;\n    transform: translateY(-50%) translateX(-6px);\n}\n.has-tooltip[data-position=\"left\"]:hover::before {\n    opacity: 1;\n    visibility: visible;\n    transform: translateY(-50%) translateX(-12px);\n}\n\n/* Right */\n.has-tooltip[data-position=\"right\"]::before {\n    left: 100%;\n    top: 50%;\n    transform: translateY(-50%) translateX(6px);\n}\n.has-tooltip[data-position=\"right\"]:hover::before {\n    opacity: 1;\n    visibility: visible;\n    transform: translateY(-50%) translateX(12px);\n}",
