      "css": "/* Write your CSS styling here */\n:root {\n  --primary: #38bdf8;\n  --bg-dark: #0b0f19;\n  --card-bg: #1e293b;\n  --text-main: #f8fafc;\n  --text-muted: #94a3b8;\n  --font-family: 'Plus Jakarta Sans', sans-serif;\n}\n\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  font-family: var(--font-family);\n  background-color: var(--bg-dark);\n  color: var(--text-main);\n  min-height: 100vh;\n  padding: 2rem;\n}",
