export function getProblemBySlug(slug: string): ProblemItem | undefined {
  const normalized = slug.toLowerCase().replace(/^\d+-/, "");
  return PROBLEMS_DATA.find((p) => p.slug === normalized || p.folder === slug || p.slug === slug);
}
